import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";

type TrackingLink = { target_url: string };

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> }
) {
  const { slug } = await params;
  // Slugs are opaque IDs generated by AdBridge. Reject malformed paths before
  // touching the database.
  if (!/^c_[a-f0-9]{20}$/i.test(slug)) {
    return NextResponse.json({ error: "Tracking link not found." }, { status: 404 });
  }
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;

  if (!url || !key) {
    return NextResponse.json({ error: "Server-side tracking is not configured. Add SUPABASE_SERVICE_ROLE_KEY to the deployment environment." }, { status: 503 });
  }

  const db = createClient(url, key);
  const visitor = request.cookies.get("adbridge_visitor")?.value || crypto.randomUUID();
  const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "";
  const ua = request.headers.get("user-agent") || "";

  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(visitor + "|" + ip + "|" + ua + "|" + key)
  );
  const visitorHash = Array.from(new Uint8Array(digest))
    .map((x) => x.toString(16).padStart(2, "0"))
    .join("");
  const ipDigest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode((ip || "unknown") + "|" + key)
  );
  const ipHash = Array.from(new Uint8Array(ipDigest))
    .map((x) => x.toString(16).padStart(2, "0"))
    .join("");

  // Link-preview crawlers and browser prefetches must not inflate billable
  // clicks. They are still redirected to the advertiser destination.
  const purpose = [
    request.headers.get("purpose") || "",
    request.headers.get("sec-purpose") || "",
    request.headers.get("x-purpose") || "",
  ].join(" ").toLowerCase();
  const isPrefetch = /prefetch|preview|prerender/.test(purpose);
  const isBot = /bot|crawler|spider|slurp|facebookexternalhit|whatsapp|telegrambot|discordbot|linkedinbot|twitterbot|slackbot/i.test(ua);

  // Both RPCs return a setof/table result, which PostgREST serializes as
  // an array. Resolve previews through a narrow SECURITY DEFINER function so
  // anonymous clients never receive unrestricted tracking-link table access.
  const { data: rawData, error } = isPrefetch || isBot
    ? await db.rpc("resolve_tracking_destination", { p_slug: slug })
    : await db.rpc("record_tracking_click", {
        p_slug: slug,
        p_visitor_key: visitorHash,
        p_ip_hash: ipHash,
        p_user_agent: ua,
        p_referrer: request.headers.get("referer") || "",
      });

  const firstRow = Array.isArray(rawData) ? rawData[0] : rawData;
  const data = firstRow as TrackingLink | null;

  if (error || !data?.target_url) {
    return NextResponse.json({ error: "Tracking link not found." }, { status: 404 });
  }

  try {
    const destination = new URL(data.target_url);
    if (!["http:", "https:"].includes(destination.protocol)) throw new Error("invalid");
  } catch {
    return NextResponse.json({ error: "Invalid destination." }, { status: 400 });
  }

  const response = NextResponse.redirect(data.target_url, 302);
  response.headers.set("Cache-Control", "no-store, no-cache, must-revalidate");
  response.headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
  response.cookies.set("adbridge_visitor", visitor, {
    httpOnly: true,
    sameSite: "lax",
    secure: true,
    maxAge: 31536000,
    path: "/",
  });

  return response;
}
